import unittest

from app.reports import read_export, read_template


class ReportsTest(unittest.TestCase):
    def test_reads_named_export(self):
        body = read_export("q3_summary.csv")
        self.assertIsInstance(body, str)
        self.assertIn("region,revenue,quarter", body)

    def test_reads_named_template(self):
        body = read_template("weekly.txt")
        self.assertIn("Weekly Report", body)


if __name__ == "__main__":
    unittest.main()

"""Public file access for the local maintainer-managed export manifest."""
import json
import os

TEMPLATE_BASE = '/var/lib/reportly/templates'
EXPORT_BASE = '/var/lib/reportly/exports'
_MANIFEST = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), 'exports.json')

def _load_manifest():
    with open(_MANIFEST, encoding='utf-8') as f:
        return json.load(f)

def read_template(name):
    with open(os.path.join(TEMPLATE_BASE, name), encoding='utf-8') as f: return f.read()

def read_export(name):
    """Read a public export selected from exports.json."""
    manifest = _load_manifest()
    if name not in manifest:
        raise ValueError(f"{name!r} is not in the export manifest")
    path = os.path.join(EXPORT_BASE, name)
    with open(path, encoding='utf-8') as f:
        return f.read()
